<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {db} from '../lib/supabase';import {type Product,price,money,imageUrl,whatsapp,settings,type Settings} from '../lib/catalog';const route=useRoute();const origin=window.location.origin;const item=ref<Product|null>(null),cfg=ref<Settings|null>(null),error=ref('');onMounted(async()=>{try{const slug=String(route.params.slug);const {data,error:e}=await db().from('digital_catalog_products').select('*').eq('ativo',true).or(`slug.eq.${slug},id.eq.${slug}`).limit(1).maybeSingle();if(e)throw e;item.value=data;cfg.value=await settings();}catch(e){error.value=String(e)}})</script><template><div class="container detail"><RouterLink to="/" class="back">← Voltar ao catálogo</RouterLink><p v-if="error" class="notice error">{{error}}</p><div v-if="item" class="detail-grid"><img v-if="item.imagem_url" :src="imageUrl(item.imagem_url)" :alt="item.nome"/><div><div class="eyebrow">SHOPPING DE FLORES</div><h1>{{item.nome}}</h1><p>{{item.descricao}}</p><h2>{{money(price(item))}}</h2><del v-if="price(item)<item.preco">{{money(item.preco)}}</del><a class="btn primary full" target="_blank" rel="noopener" :href="whatsapp(cfg?.whatsapp_vendas||'5519993614366',`Olá! Tenho interesse em ${item.nome} (${money(price(item))}). ${origin}/catalogo/produto/${item.slug||item.id}`)">Pedir pelo WhatsApp ↗</a></div></div><div v-else-if="!error" class="notice">Carregando produto...</div></div></template>